            \(runtimeGrounding)
            """
        } else {
            groundedPrompt = bundledPrompt
        }

        guard !fallback.isEmpty else {
            return groundedPrompt
        }

        return """
        \(groundedPrompt)

        Runtime caller context and user configuration:
        \(fallback)
        """
    }
}

